hdr('Step D: 系 W5 — 明示の r_0 以降で Lambda(r) の argmin が一意')

def Lambda_and_J(ej, ell, r):
    vals = []
    for (j, e) in enumerate(ej):
        if e is Infinity:
            continue
        vals.append((e + j * ell**r, j))
    if not vals:
        return (Infinity, [])
    lam = min(v for (v, j) in vals)
    return (lam, [j for (v, j) in vals if v == lam])

def r0_of(S, ell):
    """系 W5 の明示式: r_0 = 1 + max( max_{P!=P'} v_ell(det(u,u')), max_P floor(log_ell e_{m_P}) )。"""
    a = _sage_const_0 
    for i in range(len(S)):
        for j in range(i + _sage_const_1 , len(S)):
            (u1, u2) = (S[i]['u'], S[j]['u'])
            dt = ZZ(u1[_sage_const_0 ]) * ZZ(u2[_sage_const_1 ]) - ZZ(u1[_sage_const_1 ]) * ZZ(u2[_sage_const_0 ])
            if dt != _sage_const_0 :
                a = max(a, ZZ(dt).valuation(ell))
    bmax = _sage_const_0 
    for d in S:
        em = d['ej'][d['mult']]
        if em is not Infinity and em > _sage_const_0 :
            bmax = max(bmax, ZZ(em).exact_log(ell))
    return _sage_const_1  + max(a, bmax)

