hdr('Step G: 系 W7 — b <= (1/2) * per(Newt(bar tilde E))')

def lattice_perimeter(pts):
    """格子多角形（点集合の凸包）の格子周長（各辺の格子長の和）。"""
    P = Polyhedron(vertices=[list(p) for p in pts])
    if P.dim() < _sage_const_1 :
        return _sage_const_0 
    vs = [tuple(ZZ(t) for t in v) for v in P.vertices_list()]
    if P.dim() == _sage_const_1 :
        (a, b) = (vs[_sage_const_0 ], vs[-_sage_const_1 ])
        return _sage_const_2  * gcd(ZZ(b[_sage_const_0 ]) - ZZ(a[_sage_const_0 ]), ZZ(b[_sage_const_1 ]) - ZZ(a[_sage_const_1 ]))
    tot = _sage_const_0 
    n = len(vs)
    # 頂点は Polyhedron が返す順が凸順とは限らないので角度でソートする代わりに
    # 各辺（1 次元の面）から直接取る
    tot = _sage_const_0 
    for f in P.faces(_sage_const_1 ):
        w = [tuple(ZZ(t) for t in v) for v in f.as_polyhedron().vertices_list()]
        if len(w) == _sage_const_2 :
            tot += gcd(ZZ(w[_sage_const_1 ][_sage_const_0 ]) - ZZ(w[_sage_const_0 ][_sage_const_0 ]), ZZ(w[_sage_const_1 ][_sage_const_1 ]) - ZZ(w[_sage_const_0 ][_sage_const_1 ]))
    return tot

