def rho_of(u, q, ell, M):
    """P = (u) と Q = (q) の P^1(Z/ell^M) での近さ: v_ell(det(u,q))（M で頭打ち）。"""
    dt = ZZ(u[_sage_const_0 ]) * ZZ(q[_sage_const_1 ]) - ZZ(u[_sage_const_1 ]) * ZZ(q[_sage_const_0 ])
    if dt % ell**M == _sage_const_0 :
        return M
    return ZZ(dt).valuation(ell)

